double d;
adcs_vec3_t zero = {0.0, 0.0, 0.0};

if ((c == NULL) || (body == NULL) || (reference == NULL) || (innovation == NULL) || (angle == NULL))
    return ADCS_E_NULL;

if ((!adcs_is_finite_vec3(body)) || (!adcs_is_finite_vec3(reference)) ||
    (!isfinite(c->m[0][0])) || (!isfinite(c->m[0][1])) || (!isfinite(c->m[0][2])) ||
    (!isfinite(c->m[1][0])) || (!isfinite(c->m[1][1])) || (!isfinite(c->m[1][2])) ||
    (!isfinite(c->m[2][0])) || (!isfinite(c->m[2][1])) || (!isfinite(c->m[2][2]))) {
    *innovation = zero;
    *angle = (double)INFINITY;
    return ADCS_E_RANGE;
}

if (adcs_vec3_normalize(body, ADCS_EPS_NORM, &b) != ADCS_OK) {
    *innovation = zero;
    *angle = (double)INFINITY;
    return ADCS_E_RANGE;
}
if (adcs_vec3_normalize(reference, ADCS_EPS_NORM, &r) != ADCS_OK) {
    *innovation = zero;
    *angle = (double)INFINITY;
    return ADCS_E_RANGE;
}
p_raw = adcs_mat3_mul_vec(c, &r);
if (adcs_vec3_normalize(&p_raw, ADCS_EPS_NORM, &p) != ADCS_OK) {
    *innovation = zero;
    *angle = (double)INFINITY;
    return ADCS_E_RANGE;
}

cross = adcs_vec3_cross(&b, &p);
d = adcs_vec3_dot(&b, &p);
d = ADCS_CLAMP(d, -1.0, 1.0);

*innovation = cross;
*angle = atan2(adcs_vec3_norm(&cross), d);
return ADCS_OK;
}

